class ResourceSaver {
 public:
  enum class WaitState {
    kNotWaiting,
    kWaiting
  };

  void HandleResourceReception(const std::vector<GURL>& resources_list,
                               const std::vector<Referrer>& referrers_list,
                               const std::vector<GURL>& frames_list) {
    if (wait_state_ != WaitState::kWaiting)
      return;

    if (resources_list.size() != referrers_list.size())
      return;

    int64_t total_items = resources_list.size() + frames_list.size();
    if (download_ && download_->GetTotalBytes() != -1)
      download_->UpdateTotalBytes(total_items);

    for (size_t i = 0; i < resources_list.size(); ++i) {
      const GURL& resource_url = resources_list[i];
      const Referrer& referrer = referrers_list[i];

      if (!resource_url.is_valid())
        continue;

      SaveItem item(resource_url, referrer, GURL());
      waiting_queue_.push_back(item);
    }

    for (const GURL& frame_url : frames_list) {
      if (!frame_url.is_valid())
        continue;

      SaveItem item(frame_url, Referrer(), GURL());
      waiting_queue_.push_back(item);
    }

    if (waiting_queue_.empty()) {
      // Treat as user cancellation
      return;
    }

    wait_state_ = WaitState::kNotWaiting;
    StartSaving();
  }

 private:
  std::vector<SaveItem> waiting_queue_;
  WaitState wait_state_ = WaitState::kNotWaiting;
  Download* download_ = nullptr;

  void StartSaving() {
    // Implementation as needed
  }
};

